        '받는 물리 피해 감소 +10%, 모든 원소 저항 +15%': 'Physical damage taken reduction +10%, all elemental resistances +15%',
        '플레이어와 소환수 생명력 흡수 +3.5%': 'Life leech +3.5% for you and your minions',
        '소환수 한도 +1, 소환수 공격 속도 25% 증폭': 'Summon cap +1, 25% more minion attack speed',
        '소환수의 기본 공격력과 공격적인 추가 스탯의 40%를 플레이어가 가짐, 소환수 생명력 등 방어적인 소환 옵션은 전이되지 않으며 소환수는 공격하지 않음': "You gain 40% of your minions' base attack power and offensive extra stats; defensive minion options such as minion life do not transfer, and minions do not attack",
        '저항 관통 +25%, 플레이어 저항 관통이 소환수 공격에도 100% 적용. 소환수 공격이 대상 주변 1칸의 적도 관통': 'Resistance penetration +25%; your resistance penetration applies 100% to minion attacks. Minion attacks also pierce enemies within 1 cell of the target',
        '플레이어 공격력(타격당 기본 피해)의 25%를 소환수 타격에 더하고, 소환수 공격력의 25%를 플레이어 타격에 더함': 'Adds 25% of your attack power (base damage per hit) to minion hits, and 25% of minion attack power to your hits',
        '소환수 한도 +3': 'Summon cap +3',
        '소환수 한도가 1.5배가 되고 최대 한도가 12로 증가합니다. 살아 있는 소환수 중 현재 생명력이 가장 낮은 하위 1/3(최대 4기)은 유령이 되어 피해를 받지 않고 칸을 점유하지 않습니다.': 'Summon cap is 1.5x and the maximum cap rises to 12. Among living minions, the lowest third by current life (up to 4) become ghosts that take no damage and occupy no cell.',
        '상태이상 지속 피해 유발 기준 피해가 실제 타격의 2배로 계산': 'Ailment damage over time is based on double the actual hit damage',
        '지속 피해 배율의 5%만큼 모든 저항 상승, 0.5%만큼 최대 저항 상승(내림). 가장 높은 비-제한 원소 저항이 주는 상태이상 저항 +100% (공동 최고 저항은 모두 적용)': 'All resistances rise by 5% of your damage over time multiplier and maximum resistances by 0.5% (rounded down). Ailment resistance from your highest uncapped elemental resistance +100% (ties all apply)',
        '상태이상에 걸린 적이 사망 시 남은 상태이상을 모든 주변 적에게 확산': 'When an ailed enemy dies, its remaining ailments spread to all nearby enemies',
        '영구 은신: 이동 속도 +20%, 치명타 피해 배율 +25%, 회피 20% 증폭. 회피 성공 시 다음 타격에만 회피 30% 증폭': 'Permanent stealth: movement speed +20%, critical damage multiplier +25%, 20% more evasion. After a successful evade, 30% more evasion against the next hit only',
        '적이 상태이상일 때 주는 피해 20% 증폭': '20% more damage to ailed enemies',
        '중독/점화/출혈 최대 중첩 +1, 상태이상 피해 35% 증폭, 상태이상 지속 시간 25% 감폭': 'Maximum poison/ignite/bleed stacks +1, 35% more ailment damage, 25% less ailment duration',
        '모든 공격이 항상 치명타, 치명타 확률의 50% 및 치명타 피해 배율의 10%가 지속 피해 배율로 전환, 치명타에 치명타 피해 배율 대신 지속 피해 배율의 20% 적용': 'All attacks always crit; 50% of critical chance and 10% of critical damage multiplier convert to damage over time multiplier; crits apply 20% of the damage over time multiplier instead of the critical damage multiplier',
        '중독/점화/출혈 최대 중첩 +2, 최대 중첩 시 1초 쿨로 누적 피해 즉시 폭발': 'Maximum poison/ignite/bleed stacks +2; at maximum stacks the accumulated damage bursts instantly (1s cooldown)',
        '점화/중독/출혈의 피해 간격 및 지속 시간 30% 감폭(같은 피해를 더 빠르게 폭발)': '30% less ignite/poison/bleed tick interval and duration (the same damage bursts faster)',
        '투사체 피해 10% 증폭, 타겟이 하나면 15% 증폭': '10% more projectile damage, 15% more with a single target',
        '공격 시 적에게 약점 노출 부여, 노출된 적이 받는 피해 10% 증가': "Attacks expose the enemy's weakness; exposed enemies take 10% increased damage",
        '이동 속도의 20%를 회피로 전환, 회피 판정에 행운, 피격/상태이상 판정에 불운': '20% of movement speed converts to evasion; evasion rolls are lucky, hit and ailment rolls against you are unlucky',
        '타겟이 하나면 공격이 100% 관통(초과 피해가 연쇄 관통, 전이마다 80%로 감쇄)': 'With a single target, attacks pierce 100% (overkill damage chains on, decaying to 80% per transfer)',
        '치명타 피해 배율 +250%, 치명타 확률 -10%p': 'Critical damage multiplier +250%, critical chance -10%p',
