        '연속 타격 불가, 연속 타격 확률을 치명타 확률로 전환(최대 100%), 치명타 피해 배율 +50%': 'No chain hits; chain hit chance converts to critical chance (up to 100%), critical damage multiplier +50%',
        '공격 속도가 1로 고정되며, 공격 속도 증가가 모두 피해량 증폭으로 전환됨': 'Attack speed is fixed at 1; all increased attack speed converts to more damage',
        '신성화 효과: 생명력 재생 +1.5%, 생명력 재생 속도 +40%': 'Consecration: life regeneration +1.5%, life regeneration rate +40%',
        '화염/냉기 피해 증가를 번개에도 100% 적용, 번개 피해가 번개 저항 무시, 번개에는 저항 관통 미적용': 'Increased fire/cold damage applies 100% to lightning; lightning damage ignores lightning resistance; resistance penetration does not apply to lightning',
