        '받는 화염/냉기/카오스 피해의 30%를 번개로 전환, 최대 번개 저항 +3%': '30% of fire/cold/chaos damage taken is converted to lightning, maximum lightning resistance +3%',
        '생명력 재생이 ES에도 적용, 생명력 재생 +3%, 최대 생명력 +15%, 방어도/ES +40%': 'Life regeneration also applies to ES, life regeneration +3%, maximum life +15%, armor/ES +40%',
        '번개 피해의 최종 최대 피해 보정 1.35배': 'Final maximum damage roll of lightning damage ×1.35',
        '총 방어도의 50%를 ES로, 총 ES의 50%를 방어도로 전환, ES 재충전 시작 50% 가속': '50% of total armor converts to ES and 50% of total ES to armor; ES recharge starts 50% faster',
        'ES 0 시 4초간 ES 100% 재생, 동안 번개 피해 +75% (쿨 4초, 중첩불가)': 'At 0 ES, regenerate 100% ES over 4s and gain lightning damage +75% meanwhile (4s cooldown, no stacking)',
