        '피격 시 4초간 방어도 +11% (최대 5중첩, 곱연산), 5중첩 소모 반사 피해 후 2중첩 유지': 'When hit, armor +11% for 4s (up to 5 stacks, multiplicative); at 5 stacks they are spent to reflect damage and 2 stacks remain',
