        '원소 저항 관통 +30%, 원소 저항 관통이 -300%까지 확장됨': 'Elemental resistance penetration +30%, and it can push resistances down to -300%',
        '모든 피해가 카오스 피해가 됨. 카오스 피해 10% 증폭': 'All damage becomes chaos damage. 10% more chaos damage',
        '지속 피해 배율 20% 증폭, 주문 내장 피해 20% 증가, 즉발 피해 10% 감폭': '20% more damage over time multiplier, 20% increased spell base damage, 10% less instant damage',
        '에너지 보호막 재생 불가, 흡수가 에너지 보호막에 대신 적용': 'Energy shield cannot regenerate; leech applies to energy shield instead',
        '각 원소 저항 최대치 초과분의 25%만큼 카오스 저항 증가': 'Chaos resistance increased by 25% of each elemental resistance above its maximum',
        'DOT 틱 속도 +50%, 지속시간 -50%': 'DoT tick rate +50%, duration -50%',
        '저항 관통 +21%, 치명타 불가, 치명타 확률의 50%가 저항 관통으로 전환. 공격 피해가 100%~(100+(저항 관통+치명타 피해 배율)의 50%)% 사이에서 무작위로 결정됨': 'Resistance penetration +21%, cannot crit, 50% of critical chance converts to resistance penetration. Attack damage is randomly chosen between 100% and (100 + 50% of (resistance penetration + critical damage multiplier))%',
        '에너지 보호막 50% 이상에서 피해 10% 증폭. 공격 시 가능하면 생명력 4%를 소모해 해당 공격의 피해 10% 증폭': '10% more damage at 50% energy shield or above. When attacking, spend 4% life if possible for 10% more damage on that attack',
        '주얼 슬롯 2칸 추가, 카오스 피해 15% 증폭, 생명력 회복 효과 50% 감폭': 'Jewel slots +2, 15% more chaos damage, 50% less life recovery',
        '저주 최대치 +1. 카오스 피해로 적 처치 시 50% 확률로 시체 폭발(적 최대 생명력의 20%를 카오스 피해로 주변에). 모든 카오스 피해 적중 시 적에게 위축 부여(최대 10중첩, 1중첩당 받는 카오스 피해 +2%)': 'Curse limit +1. Killing an enemy with chaos damage has a 50% chance to explode the corpse (20% of its maximum life as chaos damage nearby). Every chaos damage hit applies Wither (up to 10 stacks, +2% chaos damage taken per stack)',
        '소환수 기본 피해 15% 증폭': '15% more minion base damage',
        '가장 가까운 소환수에게 플레이어가 받는 피해의 50%를 전달. 해당 피해로 소환수 사망 시 부활 시간 30% 단축': '50% of damage you take is passed to the nearest minion. If that damage kills the minion, its revive time is 30% shorter',
