        '어린 눈': 'Young Bud',
        '가지치기의 연쇄 균열 → 갈래 베기 → 십자 강타. 빙결 지대를 벗어난 뒤 마무리의 빈틈을 노립니다.': "Pruning's chain cracks → forked slash → cross slam. Step out of the frozen ground, then strike the opening after the finisher.",
        '썩음 웅덩이와 사도의 갈래 공격이 겹칩니다. 부식 지대 밖에서 삼키기가 끝난 뒤 반격합니다.': "Rot pools overlap with the apostles' forked attacks. Counter from outside the corroded ground once the swallow ends.",
        '갈래 사격과 광선, 목격한 보스의 메아리가 이어집니다. 마지막 파동 뒤 공격이 멎습니다.': 'Forked shots, beams, and echoes of the bosses it has witnessed follow one another. The attacks stop after the final wave.',
        '성화가 남은 바닥을 피하며 갈래 사격과 광선을 견딥니다. 검은 태양이 꺼지면 반격합니다.': 'Avoid the floor where the sacred flame lingers and weather the forked shots and beams. Counter when the black sun goes out.',
        '돌진 경로와 뿌리 촉수가 번갈아 열립니다. 부식 지대를 벗어나 삼키기 뒤의 긴 빈틈을 노립니다.': 'Charge lanes and root tentacles open in turn. Leave the corroded ground and aim for the long opening after the swallow.',
