        '적이 부적을 떨어뜨립니다.': 'Enemies drop talismans.',
        '세계수 기운': 'World Tree Aura',
        '지역 지도 장비에 그 지역 전용 옵션이 붙습니다.': "Equipment from region maps gets that region's exclusive affixes.",
        '타오른 잿불가지로 장비를 한 번 더 타락시킬 수 있습니다.': 'A Burning Ember Branch can corrupt an item one more time.',
        '기폭제로 장비의 품질 속성을 고른 태그로 바꿀 수 있습니다.': "Catalysts can change an item's quality attribute to a chosen tag.",
        '목걸이에 기름 셋을 발라 패시브 노드 하나를 새길 수 있습니다.': 'Apply three oils to an amulet to engrave one passive node.',
        '기름 둘째 자리': 'Second oil slot',
        '목걸이 기름 둘째 자리가 해금됩니다.': 'Unlocks the second oil slot on amulets.',
        '보스가 남긴 기억으로 그 보스에게 다시 도전할 수 있습니다. 1~3단계까지 해금됩니다.': 'A memory left by a boss lets you challenge it again. Tiers 1 to 3 are unlocked.',
        '보스 변이체': 'Boss mutants',
        '모든 보스가 드물게 변이체로 나오고, 처음 잡은 변이마다 보상을 줍니다.': 'Every boss rarely appears as a mutant, and each mutation gives a reward when first defeated.',
        '기억 던전 4, 5': 'Memory dungeon 4, 5',
        '기억 던전 4, 5단계가 해금됩니다.': 'Unlocks memory dungeon tiers 4 and 5.',
        '나이테 원정': 'Ring Expedition',
        '길잡이에게서 얻은 주사위로 이동하고, 보스를 처치해 지도 보상을 받을 수 있습니다.': 'Move with dice from the guide and defeat bosses to claim map rewards.',
        '그 지역 색의 씨앗과 수액, 불씨의 흉터를 얻을 수 있습니다.': "You can obtain seeds and sap of that region's color, and Ember Scars.",
        '콘텐츠 방 +1': 'Content rooms +1',
        '지도마다 콘텐츠 방이 하나 늘어납니다.': 'Each map gains one more content room.',
        '콘텐츠 방 +2': 'Content rooms +2',
        '지도마다 콘텐츠 방이 하나 더 늘어납니다.': 'Each map gains another content room.',
        '뿌리 기억': 'Root Memory',
        '그루터기 함의 봉인 칸이 1칸 늘어납니다.': 'The Stump Box gains one more seal cell.',
        '그루터기 함 틀의 아래 보석으로 생육함을 엽니다. 생육함에 놓은 그루터기 아이템은 효과 없이 경험치만 받습니다.': 'The gem under the Stump Box frame opens the nursery. Stump items placed in the nursery gain experience only, with no effect.',
        '루프마다 3점을 받아 그루터기 아이템을 접붙일 수 있습니다.': 'Receive 3 points each loop to graft stump items.',
        '고대 씨앗': 'Ancient Seed',
        '공명과 규율에서 어느 색이든 되고 이웃 접붙이기가 +1 되는 씨앗이 묘목장과 최종 보스에서 나옵니다.': 'A seed that counts as any color for resonance and discipline and gives neighbors +1 grafting drops from the nursery and the final boss.',
        '시간 인식': 'Time Awareness',
