        '방치 중 전투 효율이 늘어납니다.': 'Combat efficiency while idle increases.',
        '가방 확장': 'Bag expansion',
        '장비 가방이 1페이지(100칸) 늘어납니다.': 'The equipment bag gains one page (100 cells).',
