        '그루터기 함 보관함이 25칸 늘어납니다.': 'The Stump Box storage gains 25 cells.',
        '봉인 칸': 'Seal cell',
        '루프가 바뀌어도 아이템이 사라지지 않는 칸이 하나 늘어납니다. 첫 칸에는 포식이 함께 해금됩니다.': 'Gain one more cell whose items survive the loop. The first cell also unlocks Devour.',
