        '일반 아이템을 마법 아이템으로 만들고 옵션을 부여합니다. 마법 아이템의 옵션은 1~2줄로 다시 굴립니다.': 'Turns a normal item into a magic item with affixes. On a magic item it rerolls the affixes to 1 or 2 lines.',
