        '무기가 많이 나옵니다': 'Many weapons drop',
        '장신구 함': 'Jewelry Box',
        '목걸이, 반지, 허리띠가 많이 나옵니다': 'Many amulets, rings and belts drop',
        '갑주 창고': 'Armor Storehouse',
        '방어구가 많이 나옵니다': 'Many armor pieces drop',
        '고유의 메아리': 'Echo of Uniques',
        '고유 장비가 더 자주 나옵니다': 'Unique items drop more often',
        '타락한 땅': 'Corrupted Ground',
        '타락 장비가 자주 나옵니다': 'Corrupted items drop often',
        '쌍둥이 그림자': 'Twin Shadow',
        '같은 장비가 겹쳐 나옵니다': 'The same item drops in duplicate',
        '지도 제작자': 'Cartographer',
        '지도석이 많이, 더 좋고 높게 나옵니다': 'More, better and higher-tier map stones drop',
        '각인 무덤': 'Engraving Grave',
        '각인이 자주 나옵니다': 'Engravings drop often',
        '보급 행렬': 'Supply Convoy',
        '보급 상자가 늘고 좋아집니다': 'More and better supply chests',
        '붐비는 방': 'Crowded Rooms',
        '콘텐츠 방이 하나 더, 황금 방이 잘 생깁니다': 'One more content room, and golden rooms appear more',
        '정예 행렬': 'Elite Procession',
        '정예가 늘고 희귀도가 오릅니다': 'More elites and higher rarity',
        '보스의 꿈': "Boss's Dream",
        '보스의 기억과 변이체가 잘 나옵니다': 'Boss memories and mutants appear more',
        '뿌리의 메아리': 'Echo of Roots',
        '10등급 이상 지도에서 뿌리를 품은 몬스터가 자주 나옵니다': 'Root-bearing monsters appear often on maps of tier 10 or higher',
        '치명타 확률과 치명타 피해를 크게 억제합니다.': 'Heavily suppresses critical chance and critical damage.',
        '방어도와 피해 감소로 큰 한 방을 버팁니다.': 'Withstands big hits with armor and damage reduction.',
        '짧은 시간에 반복 적중하는 공격의 피해를 줄입니다.': 'Reduces damage from attacks that hit repeatedly in a short time.',
        '느린 대신 강하고 저항을 관통하는 공격을 사용합니다.': 'Uses slow but strong, resistance-penetrating attacks.',
        '빠른 연속 공격과 높은 치명타 확률로 압박합니다.': 'Pressures with fast consecutive attacks and high critical chance.',
        '생명력 위에 큰 에너지 보호막을 추가로 두릅니다.': 'Wraps a large energy shield over its life.',
        '높은 회피로 명중이 낮은 공격을 흘려냅니다.': 'High evasion lets low-accuracy attacks slip past.',
        '방어도와 피해 감소로 물리 타격을 억제합니다.': 'Suppresses physical hits with armor and damage reduction.',
        '무거운 물리 충돌과 운석 장갑이 중심인 은하입니다.': 'A galaxy centered on heavy physical collisions and meteor plating.',
        '모든 적이 생명력 위에 성간 보호막을 두르는 은하입니다.': 'A galaxy where every enemy wraps an interstellar shield over its life.',
        '주 피해와 카오스 피해가 겹치는 이중성 은하입니다.': 'A binary-star galaxy where main damage and chaos damage overlap.',
        '높은 치명타와 저항 관통으로 방어의 빈틈을 심판합니다.': 'Judges gaps in your defense with high crits and resistance penetration.',
        '빠른 공격과 높은 회피로 완성 빌드를 추격하는 은하입니다.': 'A galaxy that hunts finished builds with fast attacks and high evasion.',
        '위협을 낮춰 처음 연결하는 항로입니다.': 'A route that lowers the threat for a first connection.',
        '성간 잔해를 회수해 탐사 보상을 높입니다.': 'Recovers interstellar debris to raise exploration rewards.',
        '강한 개체를 추적해 밀도 높은 보상을 노립니다.': 'Tracks strong specimens for dense rewards.',
        '불안정한 균열을 가로질러 큰 수익을 노립니다.': 'Crosses an unstable rift for a big payoff.',
        '빨라지는 성운 폭풍 속에서 공명 잔광을 수확합니다.': 'Harvests resonance afterglow in an accelerating nebula storm.',
        '드물게 관측되는 흑성 신호입니다. 위험과 보상이 크게 증폭됩니다.': 'A rarely observed dark-star signal. Both danger and reward are greatly amplified.',
        '봉인된 보물함': 'Sealed Treasure Chest',
        '이제 탐험 중 봉인된 보물함을 발견할 수 있습니다.': 'You can now find sealed treasure chests while exploring.',
        '매복': 'Ambush',
        '이제 탐험 중 매복을 만날 수 있습니다.': 'You can now run into ambushes while exploring.',
        '알집': 'Egg Cluster',
        '이제 탐험 중 알집을 발견할 수 있습니다.': 'You can now find egg clusters while exploring.',
