        '루프 19': 'Loop 19',
        '루프 20': 'Loop 20',
        '밑거름의 우물 바닥에서 깨어난 뿌리없는 자가 잔뿌리 괴물들에게 습격당하던 은둔자 하켄을 구하고, 위쪽 중정으로 오르는 통로를 개척한다.': 'The rootless one who woke at the bottom of the Well of Compost rescues the hermit Haken from the rootlet monsters and opens a passage up toward the courtyard.',
        '루프 21': 'Loop 21',
        '루프 22': 'Loop 22',
        '루프 23': 'Loop 23',
        '루프 24': 'Loop 24',
        '루프 25': 'Loop 25',
        '루프 26': 'Loop 26',
        '루프 27': 'Loop 27',
        '루프 28': 'Loop 28',
        '루프 29': 'Loop 29',
        '루프 30': 'Loop 30',
        '중정의 수호자는 치명상을 입어도 황금 수액관이 맥동하는 한 몇 번이고 다시 일어선다.': 'However mortally wounded, the guardian of the courtyard rises again and again as long as the golden sap vessel pulses.',
        '루프 31': 'Loop 31',
        '루프 32': 'Loop 32',
        '루프 33': 'Loop 33',
        '루프 34': 'Loop 34',
