        '투사체 피해 +25%, 번개 피해 +30%, 감전된 적에게 주는 피해 +12%': 'Projectile damage +25%, lightning damage +30%, damage against shocked enemies +12%',
        '근접 피해 +25%, 공격 속도 +8%, 활성 함성마다 피해 +10%': 'Melee damage +25%, attack speed +8%, damage +10% per active warcry',
        '대지 분쇄자': 'Earth Crusher',
        '근접 피해 +25%, 강타 피해 +30%, 활성 함성마다 피해 +8%': 'Melee damage +25%, heavy blow damage +30%, damage +8% per active warcry',
        '그림자 무희': 'Shadow Dancer',
        '치명타 피해 +30%, 회피 +15%, 비껴내기 피해 감소 +8%': 'Critical damage +30%, evasion +15%, deflect damage reduction +8%',
        '독초 정원': 'Poison Herb Garden',
        '지속 피해 배율 +25%, 냉기 피해 +30%, 중독 피해 +15%': 'Damage over time multiplier +25%, cold damage +30%, poison damage +15%',
        '독연기 폭탄': 'Poison Smoke Bomb',
        '지속 피해 배율 +25%, 포션 스킬 피해 +30%, 중독 피해 +12%': 'Damage over time multiplier +25%, potion skill damage +30%, poison damage +12%',
        '맞닿은 부적의 일반 줄을 25% 더 얻습니다.': 'Gain 25% more of the normal lines of adjacent talismans.',
        '표식 방향으로 맞닿은 부적의 일반 줄을 한 번 더 얻습니다.': 'Gain the normal lines of the talisman adjacent in the marked direction once more.',
        '일반 줄 세 개를 굴림 배율 없이 가집니다.': 'Has three normal lines with no roll multiplier.',
        '맞닿은 그루터기 아이템이 없으면 스킬룬 레벨과 보조스킬룬 한도 +1, 하나면 보조스킬룬 한도 +1, 둘 이상이면 피해 +15%와 공격 속도 +10%': 'With no adjacent stump items: skill rune level and support rune limit +1. With one: support rune limit +1. With two or more: damage +15% and attack speed +10%',
        '보스에게 주는 최종 피해가 늘어나고, 생명력 5% 이하인 보스를 즉시 쓰러뜨립니다.': 'Increases final damage to bosses and instantly fells bosses at 5% life or less.',
        '세 칸 이상 떨어진 깨어난 부적의 일반 줄을 25% 더 얻습니다.': 'Gain 25% more of the normal lines of awakened talismans three or more cells away.',
        '맞닿은 그루터기 아이템 하나마다 받는 물리 피해 감소 +1%.': 'Physical damage taken reduction +1% per adjacent stump item.',
        '둘레 여덟 칸(대각선 포함)의 깨어난 부적 일반 줄을 35% 더 얻습니다.': 'Gain 35% more of the normal lines of awakened talismans in the eight surrounding cells (including diagonals).',
        '가로나 세로로 두 칸 떨어진 깨어난 부적의 일반 줄을 20% 더 얻습니다.': 'Gain 20% more of the normal lines of awakened talismans two cells away horizontally or vertically.',
        '그루터기 함에 성장 완료된 화염, 냉기, 번개 그루터기 아이템이 모두 있으면 원소 피해 +30%, 저항 관통 +6%.': 'If the Stump Box holds fully grown fire, cold, and lightning stump items, elemental damage +30% and resistance penetration +6%.',
        '그루터기 함 가장자리에 닿은 면 하나마다 모든 원소 저항 +4%, 받는 물리 피해 감소 +2%. 모서리면 생명력 +10%.': 'Per side touching the Stump Box edge: all elemental resistances +4%, physical damage taken reduction +2%. In a corner: life +10%.',
        '맞닿은 씨앗의 서로 다른 색 하나마다 화염 피해 +8%, 3색 이상이면 저항 관통 +5%.': 'Fire damage +8% per distinct color among adjacent seeds; with 3 or more colors, resistance penetration +5%.',
        '그루터기 함의 성장 완료된 씨앗 하나마다 이 부적의 일반 줄 +10%(최대 30%).': "This talisman's normal lines +10% per fully grown seed in the Stump Box (max 30%).",
        '그루터기 함에서 비활성화된 그루터기 아이템 하나마다 생명력 +5%, 방어도 +25(최대 4개).': 'Life +5% and armor +25 per deactivated stump item in the Stump Box (max 4).',
        '맞닿은 그루터기 아이템 하나마다 물리 피해 +7%, 생명력 −2%.': 'Physical damage +7% and life −2% per adjacent stump item.',
        '같은 가로줄이나 세로줄에 있는 깨어난 부적의 일반 줄을 18% 더 얻습니다.': 'Gain 18% more of the normal lines of awakened talismans in the same row or column.',
        '다른 깨어난 부적의 소환수 줄을 15% 더 얻고, 그런 부적이 4개 이상이면 소환수 한도 +1.': "Gain 15% more of other awakened talismans' minion lines; with 4 or more such talismans, minion limit +1.",
        '그루터기 함의 그루터기 아이템이 6개 이상이고 종류(계열과 색)가 모두 다르면 이 부적의 일반 줄 +40%.': "If the Stump Box holds 6 or more stump items all of different kinds (family and color), this talisman's normal lines +40%.",
        '그루터기 함의 성장 완료된 카오스 그루터기 아이템 하나마다 카오스 피해와 지속 피해 +8%(최대 5개), 생명력 −10%.': 'Chaos damage and damage over time +8% per fully grown chaos stump item in the Stump Box (max 5); life −10%.',
        '생명력 50% 이하일 때 받는 물리 피해 감소 +{v}%': 'Physical damage taken reduction +{v}% at 50% life or less',
        '생명력 50% 이하일 때 생명력 재생 +{v}%': 'Life regen +{v}% at 50% life or less',
