        '1차 전직': 'First Ascendancy',
        "1차 전직 시련을 통과했습니다.\n‘스킬트리 → 전직’에서 전직을 고르고 전직 노드를 할당하세요.": "You passed the first ascendancy trial.\nChoose an ascendancy under 'Skill Tree → Ascendancy' and allocate ascendancy nodes.",
        '화석 없음': 'No fossil',
