        '속성 홀씨': 'Elemental Spores',
        '버려진 날붙이들': 'The Forsaken Blades',
        "나무꾼이 벼리다 버린 다른 날들이 당신을 찾아옵니다.\n‘지도 → 탐험 → 강대한 적’에서 결투에 도전하세요.\n도전권 [표식: 버려진 날]은 심층 보스가 떨어뜨립니다.\n한 루프 안에 다섯 날을 모두 꺾으면 「완성작」이 모습을 드러냅니다.": "The other blades the Woodcutter forged and discarded come looking for you.\nChallenge them to a duel under 'Map → Exploration → Mighty Foes'.\nThe challenge token [Mark: Forsaken Blade] drops from deep bosses.\nBreak all five blades within one loop and the 「Finished Work」 reveals itself.",
