        '몬스터를 쓰러뜨린 만큼 내려갑니다. 정예는 {eliteKillMul}배입니다.': 'You descend as you kill monsters. Elites count {eliteKillMul}x.',
        '{value}m마다 길을 막고, 닿으면 남은 무리를 두고 바로 가디언 방으로 갑니다. 쓰러뜨려야 더 내려가고, 가디언에게 쓰러지면 잠수가 끝납니다.': 'Blocks the way every {value}m; on reaching it you leave the remaining pack and go straight to the guardian room. You must defeat it to descend further, and falling to the guardian ends the dive.',
        '초당 {st} 줄어들고, 철갑 패각충과 정예, 가디언이 부른 졸개를 쓰러뜨리면 공기 방울로 찹니다. 다 떨어지면 익사 피해를 받다가 수면으로 올라와 잠수를 시작한 사냥터로 돌아오고, 체크포인트 뒤 진행은 사라집니다.': 'Drops by {st} per second, and refills with air bubbles when you kill armored shellbugs, elites, and minions the guardian called. When it runs out you take drowning damage, surface to the hunting ground where the dive began, and progress past the checkpoint is lost.',
        '켜 두면 산소가 떨어지거나 가디언에게 쓰러져 떠오른 뒤, 사냥터 하나를 깨고 다시 잠수합니다. 가디언 앞에 막혔으면 지난 가디언 자리부터 내려가 물고기를 모읍니다. 무리에게 쓰러지거나, 리프트도 가디언 처치도 물고기도 없이 {missLimit}번 떠오르면 멈춥니다. 새 루프의 첫 잠수와 자리를 비운 동안의 정산에서는 다시 잠수하지 않습니다.': "When on, after surfacing from running out of oxygen or falling to the guardian, you clear one hunting ground and dive again. If blocked at a guardian, you descend from the previous guardian's spot and gather fish. It stops if you fall to a pack, or surface {missLimit} times with no lift, no guardian kill, and no fish. It does not re-dive on the first dive of a new loop or during away settlement.",
