        '적중 시 일정 확률로 잔향을 남겨 추가 피해를 입힙니다. 같은 적에게 여러 번 중첩될 수 있지만, 적 1기에 걸린 잔향의 남은 타격 수 합계는 최대 12회로 제한됩니다.': 'On hit, has a chance to leave an echo that deals extra damage. It can stack on the same enemy several times, but the total remaining echo hits on one enemy is capped at 12.',
