        '자신의 카오스 피해 증가 수치에 비례해 카오스 피해를 추가로 증폭합니다.': 'Further amplifies chaos damage in proportion to your increased chaos damage.',
        '카오스 피해로 적중할 때마다 적의 카오스 저항을 깎아 잠식시킵니다(중첩). 잠식 한도는 기본 20이며, 20레벨을 넘기면 레벨당 1.1씩 한도가 늘어납니다. 적이 죽거나 교체되면 잠식은 초기화됩니다.': "Each chaos-damage hit erodes the enemy's chaos resistance (stacking). The erosion cap is 20 by default and grows 1.1 per level above 20. Erosion resets when the enemy dies or is replaced.",
