        "레벨이 올라 스킬트리 포인트를 얻었습니다.\n‘스킬트리’에서 시작 지점과 이어진 노드를 골라 찍으세요.\n오른 능력치는 ‘캐릭터’에서 확인할 수 있습니다.": "You leveled up and gained a skill tree point.\nIn 'Skill Tree', choose a node connected to the starting point.\nYou can check the raised stats in 'Character'.",
        '첫 장비': 'First equipment',
        "장비를 얻었습니다. 자동 장착이 켜져 있으면 빈 칸에 맞는 장비를 바로 착용합니다.\n‘장비’에서 착용한 장비의 효과를 확인하고, 보관 중인 장비와 비교하세요.\n바꿔 입으면 전투 화면의 생명 구슬 위에 DPS 변화가 뜹니다.": "You got an item. With auto-equip on, items that fit empty slots are worn right away.\nCheck worn items' effects in 'Equipment' and compare them with stored items.\nSwapping shows the DPS change above the life orb on the battle screen.",
        '무기와 스킬룬': 'Weapons and skill runes',
        "스킬룬마다 쓸 수 있는 무기가 있습니다. 지금 무기로 쓸 수 없는 룬은 흐리게 보이고, 카드에 필요한 무기가 적혀 있습니다.\n장착한 룬을 쓸 수 없는 무기로 바꾸면 기본 공격으로 싸우다가, 맞는 무기를 들면 그 룬으로 돌아갑니다.": "Each skill rune has weapons it can be used with. Runes unusable with the current weapon appear dimmed, and the card lists the weapon needed.\nIf you switch to a weapon that cannot use the equipped rune, you fight with basic attacks until you wield a matching weapon again.",
        '스킬룬 장착': 'Equip a skill rune',
        '룬을 선택해 효과를 확인하고 ‘장착’을 누르세요. 선택한 룬에 따라 자동 전투가 달라집니다.': "Select a rune to see its effects and press 'Equip'. Auto-battle changes with the chosen rune.",
        '그루터기 함에 심기': 'Plant in the Stump Box',
        '보관함의 씨앗을 누르고 그루터기 함의 빈 칸을 누르세요. 수액도 같은 방법으로 배치합니다.': 'Click a seed in storage, then click an empty cell in the Stump Box. Sap is placed the same way.',
