        ', 룬 {rune}%': ', runes {rune}%',
        '첫 여정': 'First journey',
        "전투는 자동입니다. 캐릭터가 알아서 걷고 공격합니다.\n지금 할 일은 오른쪽 위 ‘목표’에 나옵니다.\n생명 구슬이 자주 비면 장비와 저항을 점검하세요.\n장비나 룬을 얻으면 그때마다 조작을 안내합니다.": "Combat is automatic. Your character walks and attacks on their own.\nWhat to do now is shown under 'Goal' at the top right.\nIf the life orb empties often, check your equipment and resistances.\nControls are explained whenever you get items or runes.",
        "레벨 2가 되어 스킬트리 포인트를 얻었습니다.\n‘스킬트리’에서 시작 지점과 이어진 노드를 골라 찍으세요.": "You reached level 2 and gained a skill tree point.\nIn 'Skill Tree', choose a node connected to the starting point.",
        "장비나 제작 재화를 처음 얻었습니다.\n‘장비’에서 아이템을 눌러 지금 착용한 장비와 비교하고 착용하세요.": "You got your first item or crafting currency.\nIn 'Equipment', click an item to compare it with what you wear and equip it.",
