        "새 룬을 얻었습니다.\n‘스킬룬’에서 룬을 눌러 효과를 보고 공격 룬을 바꿔 보세요.": "You got a new rune.\nIn 'Skill Runes', click a rune to see its effect and try switching your attack rune.",
