        '부적과 고급 수확 제작': 'Talismans and Advanced Harvest Crafting',
        '“미궁에서 건진 봉인편린에는 잘려 나간 옛 가지들의 원한이 서려 있어. 네 피를 먹여 깨우면 어떤 갑옷보다 든든한 부적이 되지. 그루터기 함의 식물로 하는 고급 수확 제작은 내가 가르쳐줄 수 있지. 조심해 독성이 강할 거야. 그만큼의 값도 받아야겠고.”': "“The Seal Shards you dredge from the labyrinth hold the grudges of old branches that were cut away. Feed them your blood to wake them and they become talismans sturdier than any armor. Advanced harvest crafting with the Stump Box's plants, that I can teach you. Careful, it'll be highly toxic. And I'll charge accordingly.”",
        '다음: {act} 「{title}」': 'Next: {act} “{title}”',
