        '죽은 잔뿌리들이 겹겹이 엉켜 중정으로 오르는 길을 가로막은 지하 성소.': 'An underground sanctum where layers of dead rootlets tangle and block the way up to the courtyard.',
        '아래쪽 뿌리의 수액을 빨아들여 영원을 유지하는 정원.': 'A garden that keeps its eternity by drinking the sap of the roots below.',
        '수액을 모두 빼앗긴 채 허공에 매달려 말라붙은 뿌리 숲.': 'A forest of roots hanging in the void, dried out after all their sap was taken.',
        '하층의 수액을 중정으로 실어 나르는 황금 길의 교차로.': 'A crossroads of golden paths that carry the sap of the lower layers up to the courtyard.',
        '우물에서 건진 파편을 칼날로 담금질한 비밀 공방.': 'A secret workshop where shards pulled from the well were tempered into blades.',
        '수액 공급이 끊겨 시들어 버린 정원사의 마지막 보루.': 'The last bastion of the gardener, withered after its supply of sap was cut off.',
        '수관에 모든 수액을 빼앗기고 속이 텅 비어버린 고목 도시.': 'An old-tree city hollowed out after the crown took all its sap.',
        '기억에 없는 당신의 발자국이 바닥마다 포개어져 남은 회랑.': 'A corridor where footprints of yours that you do not remember lie stacked on every floor.',
        '잘려 나간 가지들의 유해를 접붙여 마지막 고치를 품은 수관.': 'A crown that grafted the remains of severed branches and holds the last cocoon.',
        '아홉 삽목의 울음이 하나의 왕관으로 맞물린 세계수의 끝.': 'The end of the World Tree, where the cries of nine cuttings lock together into one crown.',
